def mock_parse_line_ranges(line_ranges):
    lines = []
    for lines_str in line_ranges:
        parts = lines_str.rsplit("-", 1)
        if len(parts) != 2:
            raise ValueError(f"Incorrect format {lines_str!r}")
        try:
            start = int(parts[0])
            end = int(parts[1])
        except ValueError:
            raise ValueError(f"Incorrect value {lines_str!r}")
        else:
            if start <= 0 or end <= 0:
                raise ValueError(f"Positive integers {lines_str!r}")
            if start > end:
                raise ValueError(f"start <= end {lines_str!r}")
            lines.append((start, end))
    return lines

test_cases = [
    ("1-5", "OK"),
    ("5-3", "start <= end"),
    ("0-5", "Positive integers"),
    ("-1-5", "Positive integers"),
    ("1-0", "Positive integers"),
    ("1--1", "Positive integers"),
    ("abc-5", "Incorrect value"),
    ("1-def", "Incorrect value"),
    ("1-2-3", "Incorrect value"),
    ("1", "Incorrect format"),
]

for s, expected in test_cases:
    try:
        mock_parse_line_ranges([s])
        res = "OK" if expected == "OK" else f"FAILED (no error), expected {expected}"
    except ValueError as e:
        res = "OK" if expected in str(e) or (expected == "OK" and False) else f"FAILED (error {e}), expected {expected}"
    print(f"{s!r}: {res}")
EOF
